import { IEstado } from './estado.model';
import { Materia } from './materia.model';

export class RegistroAcademico {
  private materia: Materia;
  private cuatrimestre: string;
  private nota: number;
  private estado: IEstado;

  constructor(materia: Materia, cuatrimestre: string, nota: number, estado: IEstado) {
    this.materia = materia;
    this.cuatrimestre = cuatrimestre;
    this.nota = nota;
    this.estado = estado;
  }

  getCuatrimestre(): string { return this.cuatrimestre; }

  estaAprobada(): boolean {
    return this.estado.estaAprobada();
  }

  getNota(): number {
    return this.nota;
  }

  getMateria(): Materia {
    return this.materia;
  }

  getEstado(): IEstado {
    return this.estado;
  }
}
